package io.lmctl.lmcode;

import java.util.*;

final class Verifier {
  private record Ins(int pc,Op op,int next,int target,int owner) {}
  private record Frame(int opener,int body,int exit,int parent,Op op,int counter,int end,int test) {}
  private record Edge(int from,int to) {}
  static void verify(Program p) {
    ArrayList<Ins> ins=new ArrayList<>(); ArrayList<Edge> jumps=new ArrayList<>(), whileExits=new ArrayList<>(); ArrayDeque<Frame> open=new ArrayDeque<>(); ArrayList<Frame> regions=new ArrayList<>(); HashSet<Integer> used=new HashSet<>(); boolean halted=false; Reader r=new Reader(p.code);
    while(!r.done()) { int at=r.pos, owner=open.isEmpty()?-1:open.peek().opener; Op op=Op.of(r.u8()); if(op==null) throw VmException.badBytecode("unknown opcode "+(p.code[at]&255)+" at offset "+at); int target=-1; halted=false;
      switch(op){
        case PUSH_INT->r.i64(); case PUSH_FLOAT->r.f64(); case PUSH_STR->{int x=(int)r.u32(); idx(x,p.consts.size(),"constant");} case PUSH_BOOL->{if(r.u8()>1)throw VmException.badBytecode("PUSH_BOOL operand must be 0 or 1");}
        case LOAD_LOCAL,STORE_LOCAL->{int x=r.u16();idx(x,p.locals.size(),"local slot");}
        case LOAD_CTX->{int x=r.u16();idx(x,p.contexts.size(),"context");}
        case CALL_FN,CALL_METHOD->{int x=r.u16(),a=r.u8();idx(x,p.imports.size(),"import"); var b=p.imports.get(x); if(op==Op.CALL_FN&&b.method())throw VmException.badBytecode("CALL_FN at offset "+at+" names import "+x+", which is a method"); if(op==Op.CALL_METHOD&&!b.method())throw VmException.badBytecode("CALL_METHOD at offset "+at+" names import "+x+", which is a function"); if(b.parameters().size()!=a)throw VmException.badBytecode(op+" at offset "+at+" passes "+a+" argument(s), the import takes "+b.parameters().size());}
        case MATH->{int x=r.u8();if(x>17)throw VmException.badBytecode("MATH at offset "+at+" has unknown function "+x);}
        case JUMP,JUMP_IF_FALSE,JUMP_IF_TRUE->{int rel=r.i32();if(rel<0)throw VmException.badBytecode("jump at offset "+at+" goes backwards outside a range loop");target=target(r.pos,rel);jumps.add(new Edge(at,target));}
        case FOR_RANGE->{int c=r.u16(),e=r.u16(),rel=r.i32();idx(c,p.locals.size(),"FOR_RANGE counter local");idx(e,p.locals.size(),"FOR_RANGE end local");if(c==e)throw VmException.badBytecode("FOR_RANGE at offset "+at+" reuses local "+c+" for counter and end");for(int x:new int[]{c,e}){Program.Local l=p.locals.get(x);if(!l.hidden()||!l.typeName().equals("int"))throw VmException.badBytecode("FOR_RANGE at offset "+at+" requires hidden int local "+x+", got "+(l.hidden()?"":"visible ")+l.typeName());if(!used.add(x))throw VmException.badBytecode("FOR_RANGE at offset "+at+" reuses loop local "+x);}target=target(r.pos,rel);if(target<=at)throw VmException.badBytecode("FOR_RANGE at offset "+at+" exits backwards");open.push(new Frame(at,r.pos,target,owner,op,c,e,-1));regions.add(open.peek());}
        case FOR_NEXT->{int e=r.u16(),rel=r.i32();if(open.isEmpty()||open.peek().op()!=Op.FOR_RANGE)throw VmException.badBytecode("FOR_NEXT at offset "+at+" has no matching FOR_RANGE");Frame f=open.pop();if(e!=f.end())throw VmException.badBytecode("FOR_NEXT at offset "+at+" closes the wrong range loop (end local "+e+", expected "+f.end()+")");if(r.pos+rel!=f.body())throw VmException.badBytecode("FOR_NEXT at offset "+at+" must jump to its FOR_RANGE body start "+f.body());if(rel>=0)throw VmException.badBytecode("FOR_NEXT at offset "+at+" must jump backwards");if(f.exit()!=r.pos)throw VmException.badBytecode("FOR_RANGE at offset "+f.opener()+" must exit immediately after its FOR_NEXT");p.loops.put(at,new Program.Loop(f.counter(),f.end()));target=r.pos+rel;}
        case WHILE_BEGIN->open.push(new Frame(at,r.pos,0,owner,op,0,0,-1));
        case WHILE_TEST->{int rel=r.i32();if(open.isEmpty()||open.peek().op()!=Op.WHILE_BEGIN)throw VmException.badBytecode("WHILE_TEST at offset "+at+" has no matching WHILE_BEGIN");Frame f=open.pop();if(f.test()!=-1)throw VmException.badBytecode("WHILE_BEGIN at offset "+f.opener()+" has more than one WHILE_TEST");target=target(r.pos,rel);if(rel<0)throw VmException.badBytecode("WHILE_TEST at offset "+at+" exits backwards");open.push(new Frame(f.opener(),f.body(),target,f.parent(),f.op(),0,0,at));whileExits.add(new Edge(at,target));}
        case LOOP_BACK->{int rel=r.i32();if(open.isEmpty()||open.peek().op()!=Op.WHILE_BEGIN)throw VmException.badBytecode("LOOP_BACK at offset "+at+" has no matching WHILE_BEGIN");Frame f=open.pop();if(f.test()==-1)throw VmException.badBytecode("LOOP_BACK at offset "+at+" has no matching tested WHILE_BEGIN");if(r.pos+rel!=f.opener())throw VmException.badBytecode("LOOP_BACK at offset "+at+" does not target its paired WHILE_BEGIN");if(f.exit()!=r.pos)throw VmException.badBytecode("WHILE_TEST at offset "+f.opener()+" must exit immediately after its LOOP_BACK");regions.add(f);target=r.pos+rel;}
        case HALT->{if(!open.isEmpty())throw VmException.badBytecode("HALT at offset "+at+" is inside loop");halted=true;}
        default->{ }
      }
      ins.add(new Ins(at,op,r.pos,target,owner));
    }
    if(!halted)throw VmException.badBytecode("code does not end with HALT"); if(!open.isEmpty()){Frame f=open.peek();throw VmException.badBytecode((f.op()==Op.FOR_RANGE?"FOR_RANGE":"WHILE_BEGIN")+" at offset "+f.opener()+" is not closed by "+(f.op()==Op.FOR_RANGE?"FOR_NEXT":"LOOP_BACK"));}
    Set<Integer> starts=new HashSet<>();for(Ins i:ins)starts.add(i.pc());
    for(Ins i:ins) if(i.op()==Op.STORE_LOCAL && used.contains(u16(p.code,i.pc()+1))) throw VmException.badBytecode("STORE_LOCAL at offset "+i.pc()+" writes a read-only range slot "+u16(p.code,i.pc()+1));
    for(Edge e:jumps){if(!starts.contains(e.to()))throw VmException.badBytecode("jump at offset "+e.from()+" targets "+e.to()+", not an instruction start"); Ins from=find(ins,e.from()); Frame fr=region(regions,e.from()), to=region(regions,e.to()); if(fr!=to){boolean br=fr!=null&&e.to()==fr.exit()&&((to==null&&fr.parent()==-1)||(to!=null&&to.opener()==fr.parent())); if(fr!=null&&fr.op()==Op.WHILE_BEGIN&&e.from()<fr.test()&&e.to()>fr.test())throw VmException.badBytecode("jump at offset "+e.from()+" skips its WHILE_TEST"); if(!br)throw VmException.badBytecode("jump at offset "+e.from()+" crosses a loop boundary");}}
    for(Frame f:regions)if(f.op()==Op.FOR_RANGE){if(!starts.contains(f.exit()))throw VmException.badBytecode("FOR_RANGE at offset "+f.opener()+" exits to "+f.exit()+", not an instruction start");Frame to=region(regions,f.exit());if((to==null?-1:to.opener())!=f.parent())throw VmException.badBytecode("FOR_RANGE at offset "+f.opener()+" exits to an invalid loop region");}
    for(Edge e:whileExits){if(!starts.contains(e.to()))throw VmException.badBytecode("WHILE_TEST at offset "+e.from()+" exits to an invalid loop region");Frame fr=region(regions,e.from()),to=region(regions,e.to());if(fr==null||fr.op()!=Op.WHILE_BEGIN||fr.exit()!=e.to()||((to==null?-1:to.opener())!=fr.parent()))throw VmException.badBytecode("WHILE_TEST at offset "+e.from()+" exits to an invalid loop region");}
    for(Program.Line l:p.lines)if(l.pc()>=p.code.length)throw VmException.badBytecode("line table entry points at pc "+l.pc()+", beyond the code");
    verifyStack(p,ins,regions);
  }
  private static Ins find(List<Ins> x,int pc){for(Ins i:x)if(i.pc()==pc)return i;return null;}
  private static Frame region(List<Frame> fs,int pc){Frame best=null;for(Frame f:fs)if(f.body()<=pc&&pc<f.exit()&&(best==null||f.opener()>best.opener()))best=f;return best;}
  private static void verifyStack(Program p,List<Ins> ins,List<Frame> regions){boolean hasLoop=false;for(Ins i:ins)if(i.op()==Op.FOR_RANGE||i.op()==Op.WHILE_BEGIN){hasLoop=true;break;}if(!hasLoop)return;if(ins.isEmpty())throw VmException.badBytecode("code is empty");Map<Integer,Integer> at=new HashMap<>();for(int i=0;i<ins.size();i++)at.put(ins.get(i).pc(),i);int[] depth=new int[ins.size()];Arrays.fill(depth,Integer.MIN_VALUE);ArrayDeque<Integer> q=new ArrayDeque<>();depth[0]=0;q.add(0);while(!q.isEmpty()){int ix=q.remove(),d=depth[ix];Ins in=ins.get(ix);int pop=0,push=0;boolean fall=true;switch(in.op()){case PUSH_INT,PUSH_FLOAT,PUSH_STR,PUSH_BOOL,LOAD_LOCAL,LOAD_CTX->push=1;case STORE_LOCAL,POP->pop=1;case NOT,NEG_I,NEG_F,I2F,I2S,F2S,B2S->{pop=1;push=1;}case DUP-> {pop=1;push=2;}case CALL_FN->{int x=u16(p.code,in.pc()+1),a=p.code[in.pc()+3]&255;pop=a;push=!p.imports.get(x).returns().equals("void")?1:0;}case CALL_METHOD->{int x=u16(p.code,in.pc()+1),a=p.code[in.pc()+3]&255;pop=a+1;push=!p.imports.get(x).returns().equals("void")?1:0;}case EQ,NE,ADD_I,SUB_I,MUL_I,DIV_I,MOD_I,ADD_F,SUB_F,MUL_F,DIV_F,LT_I,LE_I,GT_I,GE_I,LT_F,LE_F,GT_F,GE_F,CONCAT-> {pop=2;push=1;}case MATH->{int f=p.code[in.pc()+1]&255;pop=(f<=4||f>=10&&f<=14)?1:(f<=7||f>=15&&f<=16)?2:3;push=1;}case JUMP->{fall=false;}case JUMP_IF_FALSE,JUMP_IF_TRUE,WHILE_TEST->pop=1;case FOR_RANGE->pop=2;case FOR_NEXT->{}case LOOP_BACK->{fall=false;}case HALT->{fall=false;}default->{}}
      if(d<pop)throw VmException.badBytecode("operand stack underflow at offset "+in.pc());int after=d-pop+push;if(in.target()>=0)merge(at,depth,q,in.target(),after);if(fall){if(ix+1>=ins.size())throw VmException.badBytecode("control flow falls past the end of code");merge(at,depth,q,ins.get(ix+1).pc(),after);}}
    for(Frame frame:regions)if(frame.op()==Op.WHILE_BEGIN){Integer test=at.get(frame.test()),head=at.get(frame.opener());if(test!=null&&head!=null&&depth[test]!=Integer.MIN_VALUE&&depth[head]!=Integer.MIN_VALUE&&depth[test]!=depth[head]+1)throw VmException.badBytecode("WHILE_TEST must leave the loop-head stack depth at offset "+frame.test());}
  }
  private static void merge(Map<Integer,Integer> at,int[] d,ArrayDeque<Integer> q,int pc,int v){Integer i=at.get(pc);if(i==null)throw VmException.badBytecode("control flow targets "+pc+", not an instruction start");if(d[i]==Integer.MIN_VALUE){d[i]=v;q.add(i);}else if(d[i]!=v)throw VmException.badBytecode("inconsistent operand stack depth at control-flow join "+pc+": "+d[i]+" versus "+v);}
  private static int u16(byte[] b,int p){return ((b[p]&255)<<8)|(b[p+1]&255);} private static int target(int p,int rel){long x=(long)p+rel;if(x<0||x>Integer.MAX_VALUE)throw VmException.badBytecode("control flow target from offset "+p+" is outside the code");return (int)x;} private static void idx(int i,int n,String w){if(i<0||i>=n)throw VmException.badBytecode(w+" index "+i+" out of range ("+n+" entries)");}
}
